    node *root = NULL;
    for (int i = 0; i < size; i++) {
        // Simulate insert by creating nodes manually
        node *new_node = (node*)malloc(sizeof(node));
        new_node->ID = ids[i];
        new_node->AT = ats[i];
        new_node->BT = bts[i];
        new_node->priority = priorities[i];
        new_node->CT = 0;
        new_node->WT = 0;
        new_node->TAT = 0;
        new_node->next = NULL;

