        new_node->priority = priorities[i];
        new_node->CT = 0;
        new_node->WT = 0;
        new_node->TAT = 0;
        new_node->next = NULL;

        if (root == NULL) {
            root = new_node;
        } else {
            node *ptr = root;
            while (ptr->next != NULL) {
                ptr = ptr->next;
            }
            ptr->next = new_node;
        }
    }
    return root;
}

// Frees all nodes in a process queue.
void helper_cleanup_process_queue(node **root) {
